import { Button, ButtonProps, Divider, Message, Modal, Space, Typography } from "@arco-design/web-react";
import { IconCodeBlock, IconCodeSquare, IconLink } from "@arco-design/web-react/icon";
import CustomPage, { CustomPageProps, CustomPageStore } from "@/components/CustomPage";
import { CustomPageContext } from "@/components/CustomPage/context";
import { useContext, useEffect, useState } from "react";
import styles from './index.module.less';
import { pageDataProps } from "@/components/CustomPage/interface";
import { convertToTree, treeToFlatten } from "@/utils";

// export interface EditReactNodeProps extends Omit<CustomPageProps, 'store'> {
interface BaseProps {
    value?: pageDataProps['list'] ;
    onChange?: (val: pageDataProps['list']) => void;
}

export type EditReactNodeProps = BaseProps & {
    isComponent: boolean;
    widgets?: any;
    value?: pageDataProps;
    buttonProps?: ButtonProps;
    onChange?: (val: pageDataProps) => void;
}

function EditReactNode({ isComponent, widgets, buttonProps, ...props }: EditReactNodeProps){

    const [visible, setVisible] = useState<boolean>(false);
    const data = useContext(CustomPageContext);
    const [store] = useState(() => {
        const pageStore = new CustomPageStore({
            // node 节点类型，操作不进行修改
            control: isComponent,
            widgets,
            nodeContent: !isComponent,
            isComponent: isComponent,
        })
        if(data){
            if('pageSchema' in data){
                pageStore.settingStore.pageSchema = data.pageSchema;
            }
            if('platform' in data){
                pageStore.platform = data.platform;
            }
        }
        pageStore.settingStore.title = "模块设置"
        return pageStore;
    })




    return (
        <div>
            <Button type='primary' icon={<IconCodeSquare />}
                onClick={() => {
                    if(isComponent){
                        store.setData(props.value || {});
                    }else {
                        if(typeof props.value === "object"){
                            const list = Array.isArray(props.value)? props.value : [props.value];
                            store.setData({ list: data.pageStore.getDataList(treeToFlatten(list)) });
                        }
                    }
                    setVisible(true)
                }}
                {...buttonProps}
            >
                ReactNode
            </Button>
            <Modal visible={visible}
                alignCenter
                title={isComponent? "自定义组件" : "ReactNode"}
                focusLock={false}
                className={styles.module}
                style={{ width: '90vw' }}
                onCancel={() => {
                    setVisible(false)
                }}
                unmountOnExit
                onConfirm={() => {
                    if(props.onChange){
                        if(isComponent){
                            props.onChange(store.getData())
                        }else {
                            props.onChange(convertToTree(store.getData().list))
                        }
                        setVisible(false);
                    }else {
                        setVisible(false);
                    }
                }}
            >
                <CustomPage
                    store={store}
                />
            </Modal>
        </div>
    )
}

export default EditReactNode;